            new Quote { Id = "https://en.wikiquote.org/wiki/Martin_Luther_King_Jr.", Text = "If one is truly devoted to the religion of Jesus he will seek to rid the earth of social evils. The gospel is social as well as personal.", Author = "Martin Luther King Jr." },
            new Quote { Id = "https://en.wikiquote.org/wiki/Martin_Luther_King_Jr.", Text = "The decision which we must make now is whether we will give our allegiance to outmoded and unjust customs or whether we owe our ultimate allegiance to God and His will, rather than to man and his folkways.", Author = "Martin Luther King Jr." },
